package cn.mop.persistence;
import org.junit.jupiter.api.Test;
import java.util.*;import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
class BackupDeviceLeaseMigrationTest {
 @Test void explicitMigrationRequiresV45AndDoesNotAutoApply()throws Exception{BackupDeviceLeaseSchemaVerifier.resource();var mode=TestSchemaMigration.requestedMode(new String[]{"--apply-backup-device-coordination"});assertEquals(TestSchemaMigration.Mode.APPLY_BACKUP_DEVICE_COORDINATION,mode);assertTrue(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.SLA_REMINDERS_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_DEVICE_COORDINATION_APPLIED));assertThrows(IllegalStateException.class,()->TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.TICKET_SLA_POLICY_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(TestSchemaMigration.Mode.READ_ONLY_CHECK,TestSchemaMigration.Plan.BACKUP_DEVICE_COORDINATION_APPLIED));}
 @Test void exactCheckDefinitionsRejectMissingExtraAndModified(){var expected=BackupDeviceLeaseSchemaVerifier.CHECK_HASHES;assertDoesNotThrow(()->BackupDeviceLeaseSchemaVerifier.requireCheckHashes(expected));var missing=new TreeMap<>(expected);missing.pollFirstEntry();assertThrows(IllegalStateException.class,()->BackupDeviceLeaseSchemaVerifier.requireCheckHashes(missing));var extra=new TreeMap<>(expected);extra.put("unexpected","x");assertThrows(IllegalStateException.class,()->BackupDeviceLeaseSchemaVerifier.requireCheckHashes(extra));var modified=new TreeMap<>(expected);modified.put(modified.firstKey(),"0".repeat(64));assertThrows(IllegalStateException.class,()->BackupDeviceLeaseSchemaVerifier.requireCheckHashes(modified));}
 @Test void journalIsExplicitScopedAndFailClosed()throws Exception{try(var in=getClass().getResourceAsStream("/db/migration/"+BackupDeviceLeaseSchemaVerifier.SCRIPT)){assertNotNull(in);String sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);for(String marker:new String[]{"current_database()<>'mop_test'","PRIMARY KEY(tenant_id,asset_id,version)","FOREIGN KEY(tenant_id,asset_id)","FOR UPDATE","observed>=prior_row.lease_until","NEW.acquired_at IS NOT NULL","release_confirmation_reference IS NOT NULL","CHECK(NOT device_execution_authorized)","GRANT SELECT,INSERT"})assertTrue(sql.contains(marker),marker);assertFalse(sql.contains("SECURITY DEFINER"));assertFalse(sql.contains("GRANT UPDATE"));assertFalse(sql.contains("GRANT DELETE"));}}
}
